<template><SuperAdminLayout><main class="tickets-page"><header class="page-head"><div><h1>D. Customer Ticket History</h1><p>All previous and current tickets received from customers and staff response records</p></div><div class="actions"><button @click="print">◉ View Full History</button><button @click="print">▣ Print History</button><button @click="exportCsv">▧ Save PDF</button><button class="excel" @click="exportCsv">▤ Export Excel</button></div></header><section class="metrics"><article v-for="card in cards" :key="card.label" :class="card.tone"><i>{{card.icon}}</i><div><b>{{card.label}}</b><strong>{{card.value}}</strong></div></article></section><section class="filter-card"><h2>⚱&nbsp; Filters</h2><div class="filters"><label>Date From<input v-model="filters.from" type="date"></label><label>Date To<input v-model="filters.to" type="date"></label><label>Ticket Type<select v-model="filters.type"><option value="">All</option><option v-for="type in ticketTypes" :key="type">{{type}}</option></select></label><label>Priority<select v-model="filters.priority"><option value="">All</option><option>High</option><option>Normal</option><option>Urgent</option><option>Low</option></select></label><label>Status<select v-model="filters.status"><option value="">All</option><option>New Ticket</option><option>In Progress</option><option>Pending</option><option>Resolved</option><option>Closed</option></select></label><label>Assigned To<select v-model="filters.assigned"><option value="">All</option><option v-for="person in assignees" :key="person">{{person}}</option></select></label><label class="search">Search by Ticket No. or Subject<input v-model="filters.search" placeholder="Enter ticket no. or subject…"></label><button class="apply" @click="load">⚱ Apply Filter</button><button class="reset" @click="reset">↻ Reset</button></div></section><section class="table-card"><h2>All Received Tickets</h2><div class="table-wrap"><table><thead><tr><th>No.</th><th>Ticket No.</th><th>Sent Date</th><th>Customer / Company</th><th>Ticket Type</th><th>Subject</th><th>Priority</th><th>Assigned To</th><th>Status</th><th>View</th></tr></thead><tbody><tr v-for="(row,index) in filteredRows" :key="row.id"><td>{{index+1}}</td><td><RouterLink :to="`/super-admin/support/${row.id}`">{{row.ticket_no}}</RouterLink></td><td>{{date(row.date)}}</td><td>{{row.customer}}</td><td>{{row.type}}</td><td>{{row.subject}}</td><td><span :class="['pill',priorityClass(row.priority)]">{{row.priority}}</span></td><td>{{row.assigned_to}}</td><td><span :class="['pill',statusClass(row.status)]">{{row.status}}</span></td><td><RouterLink class="view" :to="`/super-admin/support/${row.id}`">◉</RouterLink></td></tr><tr v-if="!filteredRows.length"><td colspan="10" class="empty">No tickets match the selected filters.</td></tr></tbody></table></div></section><section class="table-card responses"><h2>Staff Response History</h2><div class="table-wrap"><table><thead><tr><th>No.</th><th>Date - Time</th><th>Ticket No.</th><th>Staff Name</th><th>Response Type</th><th>Response Details</th><th>Final Result</th><th>Status</th></tr></thead><tbody><tr v-for="(row,index) in responseRows" :key="row.id"><td>{{index+1}}</td><td>{{dateTime(row.created_at)}}</td><td>{{row.ticket_no}}</td><td>{{row.actor_name||'Super Admin'}}</td><td>{{row.activity_type}}</td><td>{{row.message||'—'}}</td><td>{{row.status==='Resolved'?'Resolved successfully':row.status==='Closed'?'Closed successfully':'Awaiting customer reply'}}</td><td><span :class="['pill',statusClass(row.status)]">{{row.status}}</span></td></tr><tr v-if="!responseRows.length"><td colspan="8" class="empty">Staff response history appears after you open a ticket.</td></tr></tbody></table></div></section></main></SuperAdminLayout></template>
<script setup>import{computed,onMounted,reactive,ref}from'vue';import{RouterLink}from'vue-router';import SuperAdminLayout from'../components/SuperAdminLayout.vue';import client from'../api/client';const rows=ref([]),responseRows=ref([]),filters=reactive({from:'',to:'',type:'',priority:'',status:'',assigned:'',search:''}),date=v=>v?new Intl.DateTimeFormat('en-CA',{month:'short',day:'numeric',year:'numeric'}).format(new Date(`${v}T00:00:00`)):'—',dateTime=v=>v?new Date(v).toLocaleString():'—',ticketTypes=computed(()=>[...new Set(rows.value.map(x=>x.type).filter(Boolean))]),assignees=computed(()=>[...new Set(rows.value.map(x=>x.assigned_to).filter(x=>x&&x!=='Unassigned'))]),filteredRows=computed(()=>rows.value.filter(x=>(!filters.type||x.type===filters.type)&&(!filters.priority||x.priority===filters.priority)&&(!filters.assigned||x.assigned_to===filters.assigned)&&(!filters.from||x.date>=filters.from)&&(!filters.to||x.date<=filters.to))),cards=computed(()=>{const x=filteredRows.value;return[{label:'Total Tickets',value:x.length,icon:'🎟',tone:'blue'},{label:'New Tickets',value:x.filter(a=>a.status==='New Ticket').length,icon:'⊕',tone:'green'},{label:'In-Progress Tickets',value:x.filter(a=>['In Progress','Pending'].includes(a.status)).length,icon:'◷',tone:'orange'},{label:'Waiting for Customer',value:x.filter(a=>a.status==='Pending').length,icon:'⌛',tone:'violet'},{label:'Resolved Tickets',value:x.filter(a=>a.status==='Resolved').length,icon:'✓',tone:'blue'},{label:'Closed Tickets',value:x.filter(a=>a.status==='Closed').length,icon:'▣',tone:'slate'}]}),statusClass=v=>String(v||'').toLowerCase().replaceAll(' ','-'),priorityClass=v=>`priority-${String(v||'').toLowerCase()}`;async function load(){const{data}=await client.get('/super-admin/tickets',{params:{search:filters.search,status:filters.status}});rows.value=data.data?.data||[]}function reset(){Object.assign(filters,{from:'',to:'',type:'',priority:'',status:'',assigned:'',search:''});load()}function print(){window.print()}function exportCsv(){const h=['ticket_no','date','customer','type','subject','priority','assigned_to','status'],csv=[h,...filteredRows.value.map(x=>h.map(k=>JSON.stringify(x[k]??'')))].map(x=>x.join(',')).join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='customer-ticket-history.csv';a.click();URL.revokeObjectURL(a.href)}onMounted(load)</script>
<style scoped>.tickets-page{color:#071d63}.page-head{display:flex;justify-content:space-between;gap:20px;align-items:start;margin-bottom:17px}.page-head h1{margin:0;font-size:2rem}.page-head p{margin:4px 0;color:#5e7096}.actions{display:flex;gap:10px;flex-wrap:wrap}.actions button,.apply,.reset{height:48px;border:1px solid #d6e0f1;border-radius:6px;background:#fff;color:#071d63;padding:0 17px;font-weight:700}.actions .excel{color:#078c42}.metrics{display:grid;grid-template-columns:repeat(6,minmax(150px,1fr));gap:14px;margin-bottom:16px}.metrics article{min-height:61px;display:flex;align-items:center;gap:13px;padding:13px 15px;border:1px solid #dce5f3;border-radius:9px;background:#fff}.metrics i{display:grid;place-items:center;width:38px;height:38px;border-radius:50%;background:#eff5ff;color:#075cff;font-size:1.35rem;font-style:normal}.metrics b,.metrics strong{display:block}.metrics b{font-size:.74rem}.metrics strong{font-size:1.5rem;margin-top:4px}.green i{color:#009844;background:#edfff4}.orange i{color:#f07100;background:#fff6e8}.violet i{color:#7236d9;background:#f6efff}.slate i{color:#162d66;background:#f0f3f8}.filter-card,.table-card{border:1px solid #dce5f3;border-radius:8px;background:#fff;margin-bottom:13px;padding:14px}.filter-card h2,.table-card h2{font-size:1rem;margin:0 0 12px}.filters{display:grid;grid-template-columns:repeat(6,minmax(110px,1fr)) 220px auto auto;gap:12px;align-items:end}.filters label{display:grid;gap:5px;font-size:.69rem;font-weight:800}.filters input,.filters select{height:36px;box-sizing:border-box;border:1px solid #cad8ed;border-radius:5px;padding:0 10px;background:#fff;color:#0c2364}.apply{background:#062c72;color:#fff;border-color:#062c72;height:37px;white-space:nowrap}.reset{height:37px;white-space:nowrap}.table-card{padding:0;overflow:hidden}.table-card h2{padding:9px 12px;margin:0;border-bottom:1px solid #dce5f3}.table-wrap{overflow:auto}table{width:100%;min-width:1030px;border-collapse:collapse;font-size:.75rem}th{background:linear-gradient(90deg,#06235f,#063887);color:#fff;white-space:nowrap}th,td{border:1px solid #dae3ef;padding:7px 10px;text-align:left}td{font-weight:600;color:#0b2160}td a{color:#0758de;text-decoration:none;font-weight:800}.view{font-size:1rem;color:#092c76!important}.pill{display:inline-block;min-width:60px;padding:3px 7px;border:1px solid #d6e3f6;border-radius:4px;text-align:center;font-size:.68rem}.priority-high{color:#e21a1a;background:#fff0f0;border-color:#ffd3d3}.priority-urgent{color:#6627da;background:#f4efff}.open,.in-progress{color:#0755dc;background:#edf5ff}.pending{color:#ed7200;background:#fff6eb}.resolved{color:#078338;background:#eaf9ef}.closed{color:#46546e;background:#f0f3f7}.empty{text-align:center;padding:24px}@media(max-width:1200px){.metrics{grid-template-columns:repeat(3,1fr)}.filters{grid-template-columns:repeat(4,1fr)}}@media(max-width:760px){.page-head{display:block}.actions{margin-top:14px}.metrics,.filters{grid-template-columns:1fr 1fr}}@media print{.sa-sidebar,.sa-topbar,.actions,.filter-card{display:none!important}}</style>
